def weighted_average(values, weights=None):
    if len(values) == 0:
        raise ValueError('values required')
    actual = weights if weights is not None else [1] * len(values)
    denominator = sum(actual)
    if len(values) != len(actual) or denominator == 0:
        raise ValueError('invalid weights')
    products = [pair[0] * pair[1] for pair in zip(values, actual)]
    return sum(products) / denominator

